INSERT INTO `productos` (`id`, `created_at`, `updated_at`, `name`, `model`, `brand`, `SAT_code`, `warranty`, `description`, `images`, `sell_price`, `subcategoria_id`, `unidad_medida`) VALUES
	(6, '2025-03-19 19:45:29', '2025-03-19 19:45:29', 'DVR 4 Canales TurboHD + 1 Canal IP / 2 Megapixel (1080p) Lite / Acusense Lite (Busqueda Inteligente Personas Vehiculos) / Audio por Coaxitron / 1 Bahia de Disco Duro / H.265+ / Salida de Vídeo Full HD', 'DS-7104HGHI-M1(C)', 'HIKVISION', '46171621', 1, 'Soporte audio por coaxitron en todos los canales Búsqueda inteligente por humanos y vehículos Compatibilidad tecnologías: HD-TVI, HD-CVI, AHD, CVBS, IP Compresión eficiente: H.265+, H.265, H.264+, H.264 5 canales: 4 TurboHD/analógicos + 1 canal IP', '["static/uploads/d9f301c5-1aec-4b1d-9f82-481c3c632e6b.png"]', 1002.00, 6, ''),
	(9, '2025-03-19 20:02:34', '2025-03-19 20:02:34', 'Gabinete de Acero IP66 Uso en Intemperie (250 x 300 x 150 mm) con Placa Trasera Interior Metálica y Compuerta Inferior Atornillable (Incluye Chapa y Llave T).', 'PST-2530-15A', 'PRECISION', '43223306', 3, 'Nivel de protección IP66 para exteriores exigentes Resistencia a impactos IK10, alta durabilidad Dimensiones compactas 250x300x150 mm Peso soportado de 30 kg para almacenamiento Cerradura de seguridad con llave PSTK2L/PSTK2K', '["static/uploads/0317ef17-2303-4edc-a0c7-14ec37f7b1d7.png", "static/uploads/eb18222c-73fa-4915-bfa0-9bbb0504e80c.webp", "static/uploads/bbdb3e45-f9dd-4040-ad1b-30d8754e95b6.webp"]', 866.00, 5, ''),
	(10, '2025-03-19 20:19:25', '2025-05-19 21:01:44', 'DVR 8 Canales TurboHD + 2 Canales IP / 2 Megapixel (1080p) Lite / Acusense Lite (Evita Falsas Alarmas) / Audio por Coaxitron / 1 Bahía de Disco Duro / H.265+ / Salida de Vídeo Full HD', 'S08-TURBO-M1', 'EPCOM PROFESSIONAL', '46171621', 5, 'Filtro inteligente de movimiento para humanos/vehículos Compatibilidad con cinco tecnologías: HD-TVI, CVI, AHD, IP Soporta hasta 10 canales: 8 analógicos, 2 IP Acceso remoto desde PC y Smartphone Compresión avanzada: H.265 Pro+ y H.264', '["static/uploads/54f207ad-8db2-4c3f-bc75-0bb2777a23e6.png", "static/uploads/5e71865b-9104-4bd3-bbd2-60bc0baf3c8e.webp", "static/uploads/d6d65490-bab8-4f97-b3b9-584daad43269.webp"]', 788.22, 6, 'H87'),
	(11, '2025-03-19 20:21:07', '2025-03-19 20:21:07', 'DVR 16 Canales TurboHD + 2 Canales IP / 2 Megapixel (1080p) Lite / Acusense Lite (Evita falsas alarmas) / Audio por Coaxitron / 1 Bahía de Disco Duro / H.265+ / Salida de VÌdeo en Full HD', 'DS-7116HGHI-M1(E)', 'HIKVISION', '46171621', 5, 'Audio por coaxitron en todos los canales Soporta búsqueda por humanos y vehículos Compatibilidad con HD-TVI, HD-CVI, AHD, CVBS, IP Soporta 18 canales: 16 TurboHD, 2 IP Compresión H.265+ optimiza almacenamiento', '["static/uploads/df861ae5-03e9-4bf8-a1dc-12e23fb78414.png", "static/uploads/7b9afc42-db7d-4c69-b12e-20e46d260c5e.webp", "static/uploads/e89d1f28-cc02-47ef-a82e-9f9eb10536a5.webp"]', 2434.00, 6, ''),
	(12, '2025-03-22 20:32:11', '2025-05-19 20:37:26', '[ColorVu] Bala TURBOHD 2 Megapíxel (1080p) / Microfono Integrado / Imagen a color 24/7 / Lente 2.8 mm / METAL / Luz Blanca 20 mts / Exterior IP66 / TVI-AHD-CVI-CVBS / dWDR', 'B8-TURBO-C/A', 'EPCOM PROFESSIONAL', '46171610', 5, 'Resolución máxima 2 MP (1920 x 1080) Iluminación mínima: 0.001 lux @ F1.0 Lente fijo 2.8 mm, apertura 105 grados Proyección luz blanca 20 metros, imagen color 24/7 Soporta 4 tecnologías, cable seleccionable', '["static/uploads/c4e81fe9-c423-4cdc-9839-d83a5bff782d.png", "static/uploads/fa135640-683f-46d7-afed-2928eaf8b4d0.webp", "static/uploads/eb628439-90db-41cb-add6-f78aae6b5fe0.webp"]', 473.29, 9, 'H87'),
	(13, '2025-03-22 20:36:44', '2025-05-19 20:55:00', 'Mini Domo PTZ IP 2 Megapixel / 4X Zoom / H.265+ / 20 mts IR EXIR / WDR 120dB / PoE / IK10 / Exterior IP66 / Ultra Baja Iluminación / Micrófono Integrado / PoE', 'PTZ-N2204I-DE3 F', 'HiLook by HIKVISION', '46171610', 5, 'Resolución máxima de 2 megapíxeles (1920 x 1080) Iluminación mínima color 0.005 lux, F1.6, AGC activado Zoom óptico 4x y digital 16x potente Compresión avanzada H.265+ eficiente Especialmente diseñado para uso exterior con IP66', '["static/uploads/56eecb95-474a-43db-b354-ee3e0fe6a94f.png", "static/uploads/874abcb3-ba61-44af-8f19-fd5cc7773b68.webp", "static/uploads/e4fcc2c5-00bb-426a-bce1-92b848a2bdb0.webp"]', 2621.75, 10, 'H87'),
	(14, '2025-03-22 20:40:26', '2025-05-20 19:38:55', 'Fuente de Poder Regulada 12 Vcc / 13.5 Vcc / 15 Vcc para 8 Cámaras / 1 Amp por Salida / Voltaje de Entrada 90 - 130 VCA / Filtro de Ruido para Cámaras 4K / Modo para Largas Distancias', 'DS-2FA1205-C8/K', 'HIKVISION', '39121004', 5, 'Voltaje de entrada 90-130 VCA para flexibilidad Tres niveles de salida: 12/13.5/15 VCC Amperaje máximo de salida: 1 Amp Dimensiones compactas: 130 x 94 x 34 mm Incluye cable tipo L de 1 metro', '["static/uploads/9e18c43e-038b-47bd-8081-bda3118e202e.png"]', 676.61, 11, 'H87'),
	(16, '2025-03-22 20:45:52', '2025-05-20 19:42:29', 'Fuente de Alimentación de 4 Salidas de 11 - 15 Vcc / 5 Amper / Voltaje de Entrada 110- 240 Vac / Fusible Termico PTC Integrado para Protección / Salida de Voltaje Inteligente hasta 3 Amper por Salida', 'PS-12-DC-4C', 'EPCOM POWERLINE', '39121009', 3, 'Compatibilidad con cámaras analógicas y TurboHD, 12.5V soporte Fuente suministra hasta 3 amperios por salida Voltaje de entrada 110-240 VCA, salida 11-15 VCC Sistema inteligente 5A distribuidos en 4 salidas Fusible térmico PTC de 6A integrado', '["static/uploads/9a634567-3033-4487-bf5c-e5c8fc8e5f31.jpg", "static/uploads/b6ac2260-a65c-4023-ac0d-40d68f276687.webp", "static/uploads/829056c1-97a3-4353-a968-2f037c5f0b11.webp"]', 221.50, 11, 'H87'),
	(17, '2025-03-22 20:48:11', '2025-05-20 19:43:46', 'Cámara IP Wi-Fi para exterior, 3 megapixel, audio doble vía, visión nocturna, notificación Push, acepta memoria Micro SD de para grabación.', 'TAPOC310', 'TP-LINK', '46171610', 3, 'Resolución 3MP con visión nocturna hasta 30 metros Detección de movimiento con notificación push instantánea Codec H.264 para compresión eficiente de video Audio bidireccional con micrófono y altavoz integrados Soporta microSD 128GB para grabación local', '["static/uploads/28382296-6968-4a1e-a8b9-26a0c4154f90.png", "static/uploads/c6e88e0d-5e36-4fd4-82b9-fc2f7b1cb152.webp", "static/uploads/a4b246e8-f9f2-4750-b70f-bb5c4c933b30.webp"]', 778.52, 12, 'H87'),
	(18, '2025-03-22 20:50:50', '2025-05-20 19:47:30', 'Energizador con tecnología SMT de 12,000Volts-1Joule/ 2500Mts Lineales de Protección / Cercas Electrificadas', 'SYSNG-V3', 'YONUSA', '46171623', 3, 'Descarga de 12,000 voltios, no letal Consumo energético de 1.2 kW/mes Respaldo de batería hasta 3 días Opcional alimentación por panel solar Alarma por atenuación o corte de voltaje', '["static/uploads/81aa5230-b01c-4faf-852d-de4d094bbeca.png", "static/uploads/df8ae00b-c7c7-477d-bad7-d56e10602cea.webp", "static/uploads/78a311f3-671c-420a-a6b4-780616054add.webp"]', 2644.40, 13, 'H87'),
